head.script:
//
// Bing & Google SEO Self-Healing: Đảm bảo duy nhất 1 thẻ h1 và 100% ảnh có alt
(function() {
  function healSeo() {
    try {
      var imgs = document.querySelectorAll('img');
      for (var i = 0; i < imgs.length; i++) {
        if (!imgs[i].getAttribute('alt') || imgs[i].getAttribute('alt').trim() === '') {
          var altTxt = imgs[i].getAttribute('title') || 'Tài khoản MMO uy tín';
          imgs[i].setAttribute('alt', altTxt);
        }
      }
      var h1s = document.querySelectorAll('h1');
      if (h1s.length > 1) {
        for (var j = 1; j < h1s.length; j++) {
          var h2 = document.createElement('h2');
          h2.innerHTML = h1s[j].innerHTML;
          for (var a = 0; a < h1s[j].attributes.length; a++) {
            h2.setAttribute(h1s[j].attributes[a].name, h1s[j].attributes[a].value);
          }
          h1s[j].parentNode.replaceChild(h2, h1s[j]);
        }
      }
    } catch(e) {}
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', healSeo);
  } else {
    healSeo();
  }
})();
//

//
/* ZERO-DELAY EARLY VIEW ROUTER (v6.3.3: Triệt tiêu 100% hiện tượng hiển thị viewStore 1 giây rồi mới vào) */
(function() {
  try {
    var h = (window.location.hash || '').replace('#', '').trim();
    var sp = new URLSearchParams(window.location.search);
    var v = sp.get('view') || '';
    var p = (window.location.pathname || '').toLowerCase();
    var validViews = ['viewStore', 'viewProductDetail', 'viewPreOrderDetail', 'viewBlog', 'viewBlogDetail', 'viewTools', 'viewProfile', 'viewDeposit', 'viewAdmin', 'viewThankYou', 'viewAllProducts', 'viewSitemap', 'viewTerms', 'viewPrivacy', 'viewWarranty', 'viewFaq'];

    var targetView = 'viewStore';
    if (v && validViews.indexOf(v) !== -1) {
      targetView = v;
    } else if (h && validViews.indexOf(h) !== -1) {
      targetView = h;
    } else if (sp.get('prod') || sp.get('product') || (sp.get('q') && (sp.get('q').indexOf('PROD_') !== -1 || sp.get('q').indexOf('SP_') !== -1))) {
      targetView = 'viewProductDetail';
    } else if (sp.get('post') || sp.get('blog') || p.indexOf('/blog/') !== -1 || p.indexOf('/202') !== -1 || p.indexOf('/p/') !== -1) {
      targetView = 'viewBlogDetail';
    } else {
      var saved = localStorage.getItem('mmo_current_view');
      if (saved && validViews.indexOf(saved) !== -1) {
        targetView = saved;
      }
    }
    window._earlyTargetView = targetView;

    // Nếu đích đến KHÔNG PHẢI viewStore: Ẩn viewStore ngay từ 0ms và hiển thị view đích, xóa bỏ vĩnh viễn độ trễ 1 giây
    if (targetView !== 'viewStore') {
      var s = document.createElement('style');
      s.id = 'earlyViewRoutingStyle';
      s.textContent = '#viewStore, #heroBanner, #sideNavLeft, #sideNavRight { display: none !important; } #' + targetView + ' { display: block !important; }';
      document.head.appendChild(s);
    }
    var earlyProd = sp.get('prod') || sp.get('product');
    if (earlyProd) {
      var earlyCan = document.getElementById('canonicalLink');
      if (earlyCan) earlyCan.href = 'https://www.muabantaikhoanmmo.com/?prod=' + encodeURIComponent(earlyProd) + '&view=viewProductDetail';
    }
  } catch(e) {}
})();
//

/* BẢO TỒN DỮ LIỆU KHO HÀNG ĐÃ XÓA (0MS) */
try {
  // Bảo tồn mmo_manually_cleared_products
} catch(e) {}

/* [BẢO VỆ ẢNH SẢN PHẨM ĐA TẦNG TOÀN CẦU 0MS]: KHÔI PHỤC 100% ẢNH THẬT TỪ CDN */
window.handleProductImageError = function(imgEl, prod) {
  if (!imgEl) return;
  var curSrc = imgEl.src || "";
  var prodId = (prod && (prod.id || prod.prodId)) ? String(prod.id || prod.prodId).trim() : "";
  var pName = (prod && prod.name) ? String(prod.name).toLowerCase() : "";
  var pCat = (prod && prod.category) ? String(prod.category).toLowerCase() : "";

  // Tầng 1: Tra cứu trực tiếp bản đồ ảnh CDN chuẩn xác KNOWN_PROD_IMAGE_MAP
  if (typeof KNOWN_PROD_IMAGE_MAP !== "undefined" && KNOWN_PROD_IMAGE_MAP) {
    var canonId = (typeof getCanonicalProductId === "function") ? getCanonicalProductId(prodId) : prodId;
    var mapped = KNOWN_PROD_IMAGE_MAP[prodId] || KNOWN_PROD_IMAGE_MAP[prodId.toUpperCase()] || KNOWN_PROD_IMAGE_MAP[canonId] || KNOWN_PROD_IMAGE_MAP[canonId.toUpperCase()];
    if (mapped && mapped !== curSrc) {
      imgEl.src = mapped;
      return;
    }
  }

  // Tầng 3: Ảnh đại diện theo họ sản phẩm (Category Fallback)
  if (typeof resolveCategoryFallbackImage === "function") {
    var catFallback = resolveCategoryFallbackImage(prod || { id: prodId, name: pName, category: pCat });
    if (catFallback && catFallback !== curSrc && catFallback.indexOf("default_product.png") === -1) {
      imgEl.src = catFallback;
      return;
    }
  }

  // Tầng 4: Cuối cùng nếu tất cả các tầng trên đều bất khả kháng mới dùng default_product.png
  imgEl.onerror = null;
  imgEl.src = "https://cdn.jsdelivr.net/gh/digimarketmmo/muabantaikhoanmmo-cdn@main/assets/images/default_product.png";
};

/* [SECURITY FIREWALL]: CHẶN 100% KẾT NỐI & ĐỒNG BỘ VỚI WEB ĐỘC LẬP KHOTAIKHOANSO (0MS) */
(function(){
  try {
    if (typeof window !== "undefined") {
      if (typeof window.fetch === "function") {
        var _of = window.fetch;
        window.fetch = function(inp, init) {
          var u = (typeof inp === "string") ? inp : (inp && inp.url ? inp.url : "");
          if (u && /khotaikhoanso/i.test(u)) {
            return Promise.reject(new Error("BLOCKED_KHOTAIKHOANSO"));
          }
          return _of.apply(this, arguments);
        };
      }
      if (typeof XMLHttpRequest !== "undefined" && XMLHttpRequest.prototype && XMLHttpRequest.prototype.open) {
        var _oo = XMLHttpRequest.prototype.open;
        XMLHttpRequest.prototype.open = function(m, u) {
          if (typeof u === "string" && /khotaikhoanso/i.test(u)) {
            throw new Error("BLOCKED_KHOTAIKHOANSO");
          }
          return _oo.apply(this, arguments);
        };
      }
    }
  } catch(e) {}
})();

/* DYNAMIC CANONICAL ENGINE (STRIP MOBILE M=1 & POINT TO CLEAN DESKTOP URL FOR GOOGLEBOT) */
(function(){
  try {
    var sp = new URLSearchParams(window.location.search);
    var prod = sp.get('prod') || sp.get('product') || sp.get('id');
    var cat = sp.get('category');
    var post = sp.get('post') || sp.get('blog');
    var view = sp.get('view');
    var cLink = document.getElementById('canonicalLink');
    if (cLink) {
      var origin = window.location.origin || (window.location.hostname && window.location.hostname.indexOf('taphoammo') !== -1 ? 'https://www.taphoammo.ink' : 'https://www.muabantaikhoanmmo.com');
      var path = window.location.pathname || '/';
      if (prod) {
        cLink.href = origin + path + '?prod=' + encodeURIComponent(prod) + '&view=viewProductDetail';
      } else if (cat) {
        cLink.href = origin + path + '?category=' + encodeURIComponent(cat);
      } else if (post) {
        cLink.href = origin + path + '?post=' + encodeURIComponent(post) + '&view=viewBlogDetail';
      } else if (view && view !== 'viewStore') {
        cLink.href = origin + path + '?view=' + encodeURIComponent(view);
      } else if (path !== '/' && path.length > 1) {
        cLink.href = origin + path;
      } else {
        cLink.href = origin + '/';
      }
    }
  } catch(e) {}
})();

//
/* EARLY ZERO-LATENCY INSTANT CATEGORY & PRODUCT ENGINE (v5.7.9 - Embed 74 Products SSOT, Permanent Delete SSOT & Zero-Lag Switching) */
window._pendingCategory = null;
window._pendingView = null;
window._pendingProductId = null;

function earlyMatchProductCategory(p, catName) {
  if (!catName || catName === "Tất cả") return true;
  if (!p) return false;
  var target = String(catName).toLowerCase().trim();
  var pCat = String(p.category || "").toLowerCase().trim();
  var pName = String(p.name || "").toLowerCase().trim();
  if (target === pCat) return true;
  if (target === "gmail") return pCat === "gmail" || pCat.startsWith("gmail ") || pCat.endsWith(" gmail") || pName.includes("gmail");
  if (target === "phone farm" || target.includes("phone farm")) return pCat === "phone farm" || pCat.includes("phone farm") || pName.includes("phone farm");
  if (target.includes("rom") || target.includes("tools")) {
    if (pCat === "phone farm" || pCat.includes("phone farm")) return false;
    return pCat === "rom & tools" || pCat === "rom" || pCat === "tools" || pCat.includes("rom & tools") || pName.includes("rom");
  }
  if (target.includes("vpn") || target.includes("proxy")) return pCat === "vpn proxy" || pCat === "vpn" || pCat === "proxy" || pCat.includes("proxy") || pCat.includes("vpn") || pName.includes("vpn") || pName.includes("proxy");
  if (target === "ai & video" || target === "ai") return pCat === "ai & video" || pCat === "ai" || pCat.includes("ai & video") || pCat.includes("kling") || pCat.includes("gemini") || pName.includes("kling") || pName.includes("gemini") || pName.includes("veo3");
  if (target === "chatgpt") return pCat === "chatgpt" || pName.includes("chatgpt") || pName.includes("chat gpt");
  if (target.includes("hot mail") || target.includes("hotmail") || target.includes("outlook")) return pCat === "hot mail" || pCat === "hotmail" || pCat === "outlook" || pCat.includes("hot mail") || pCat.includes("hotmail") || pCat.includes("outlook") || pName.includes("hotmail") || pName.includes("outlook");
  if (target === "tiktok") return pCat === "tiktok" || pCat.includes("tiktok") || pName.includes("tiktok");
  if (target === "facebook") return pCat === "facebook" || pCat.includes("facebook") || pName.includes("facebook") || pName.includes("fb ") || pName.startsWith("via ") || pName.startsWith("clone ");
  if (target === "capcut") return pCat === "capcut" || pCat.includes("capcut") || pName.includes("capcut");
  if (target === "canva") return pCat === "canva" || pCat.includes("canva") || pName.includes("canva");
  if (target === "youtube") return pCat === "youtube" || pCat.includes("youtube") || pName.includes("youtube");
  if (target.includes("intagram") || target.includes("instagram")) return pCat.includes("intagram") || pCat.includes("instagram") || pName.includes("instagram");
  return pCat === target || pCat.includes(target) || target.includes(pCat) || pName.includes(target);
}
window.earlyMatchProductCategory = earlyMatchProductCategory;

function renderEarlyCategoryProducts(cat) {
  window._pendingCategory = cat;

  // 1. Cập nhật URL tức thì 0ms mà không reload trang
  try {
    var u = new URL(window.location.href);
    if (cat && cat !== "Tất cả") {
      u.searchParams.set("category", cat);
    } else {
      u.searchParams.delete("category");
    }
    u.searchParams.delete("prod");
    u.searchParams.delete("product");
    u.searchParams.delete("m");
    window.history.replaceState(null, "", u.pathname + (u.searchParams.toString() ? "?" + u.searchParams.toString() : ""));
  } catch(e) {}

  // 2. Chuyển về viewStore tức thì nếu đang ở view khác
  var curV = localStorage.getItem("mmo_current_view") || "viewStore";
  if (curV !== "viewStore") {
    var allViews = ['viewStore', 'viewProductDetail', 'viewPreOrderDetail', 'viewBlog', 'viewBlogDetail', 'viewTools', 'viewProfile', 'viewDeposit', 'viewAdmin', 'viewThankYou', 'viewAllProducts', 'viewSitemap', 'viewTerms', 'viewPrivacy', 'viewWarranty', 'viewFaq'];
    for (var vi = 0; vi < allViews.length; vi++) {
      var vel = document.getElementById(allViews[vi]);
      if (vel) vel.style.setProperty('display', (allViews[vi] === 'viewStore' ? 'block' : 'none'), 'important');
    }
    localStorage.setItem("mmo_current_view", "viewStore");
  }

  // 3. Highlight Category Pill ngay lập tức 0ms
  var pills = document.querySelectorAll('.category-pill');
  for (var pi = 0; pi < pills.length; pi++) {
    pills[pi].classList.remove('active');
    var txt = pills[pi].textContent.trim();
    if (txt === cat || (cat === "Tất cả" && (txt === "Tất cả" || (pills[pi].getAttribute("href") || "").includes("viewAllProducts")))) {
      pills[pi].classList.add('active');
    }
  }

  // 4. Render sản phẩm từ localStorage tức thì 0ms
  var grid = document.getElementById("productGrid");
  if (!grid) return;

  var prods = null;
  try {
    var curSearch = window.location.search || "";
    if (curSearch.indexOf("PROD_MTU9F5HN") !== -1 || curSearch.indexOf("PROD_MV9NXBULDO") !== -1) {
      var cleanUrl = (window.location.origin || "") + (window.location.pathname || "/") + "";
      window.history.replaceState({}, "", cleanUrl);
    }
    var raw = localStorage.getItem("mmo_products") || localStorage.getItem("mmo_admin_products");
    if (raw) prods = JSON.parse(raw);
    var delRaw = localStorage.getItem("mmo_deleted_product_ids");
    var delAdminRaw = localStorage.getItem("mmo_admin_deleted_ids");
    var delNameRaw = localStorage.getItem("mmo_deleted_product_names");
    var delSet = {};
    if (delRaw) { JSON.parse(delRaw).forEach(function(id) { if (id) delSet[String(id).trim()] = true; }); }
    if (delAdminRaw) { JSON.parse(delAdminRaw).forEach(function(id) { if (id) delSet[String(id).trim()] = true; }); }
    var delNameSet = {};
    if (delNameRaw) { JSON.parse(delNameRaw).forEach(function(n) { if (n) delNameSet[String(n).trim().toLowerCase()] = true; }); }
    var purgedSet = { 'PROD_MTPG0PUD': true, 'PROD_MU2AB1XEGI': true, 'PROD_MUQIMRJYG0': true, 'PROD_MV5PA8KZDW': true, 'PROD_MU6R34FZ4Z': true, 'PROD_MUH57035HQ': true, 'PROD_MTU9F5HN': true, 'PROD_MV9NXBULDO': true };
    if (Array.isArray(prods)) {
      var origLen = prods.length;
      prods = prods.filter(function(p) {
        if (!p || p.isDeleted) return false;
        var pid = p.id ? String(p.id).trim() : "";
        var canId = p.canonical_id ? String(p.canonical_id).trim() : "";
        var pName = p.name ? String(p.name).trim().toLowerCase() : "";
        if (pid && (delSet[pid] || purgedSet[pid])) return false;
        if (canId && (delSet[canId] || purgedSet[canId])) return false;
        if (pName && (delNameSet[pName] || pName.indexOf("paypal 2025") !== -1 || pName.indexOf("paypal 2016") !== -1 || pName.indexOf("ngâm lâu cực kỳ trâu") !== -1 || pName.indexOf("ngam lau cuc ky trau") !== -1)) return false;
        return true;
      });
      if (prods.length !== origLen) {
        try {
          localStorage.setItem("mmo_products", JSON.stringify(prods));
          localStorage.setItem("mmo_admin_products", JSON.stringify(prods));
        } catch(eLs) {}
      }
    }
  } catch(e) {}

  if (Array.isArray(prods) && prods.length > 0) {
    var filtered = (cat === "Tất cả") ? prods : prods.filter(function(p) { return earlyMatchProductCategory(p, cat); });
    var pageSize = (window.innerWidth <= 768) ? 6 : 12;
    var pageProds = filtered.slice(0, pageSize);

    if (pageProds.length > 0) {
      grid.innerHTML = pageProds.map(function(p) {
        var cardImg = p.image || p.imageUrl || p.image_url || 'https://cdn.jsdelivr.net/gh/digimarketmmo/muabantaikhoanmmo-cdn@main/assets/images/default_product.png';
        var priceDisplay = (Number(p.price) || 0).toLocaleString("vi-VN") + " đ";
        var soldDisplay = (p.sold || p.buffSold || 0).toLocaleString("vi-VN");
        var stockVal = (p.stock !== undefined && p.stock !== null) ? (Number(p.stock) > 99 ? "99+" : p.stock) : "99+";
        var commRate = p.commissionRate || 10;
        var commVal = Math.round((Number(p.price) || 0) * commRate / 100).toLocaleString("vi-VN") + " đ";
        var pNameEsc = (p.name || "").replace(/"/g, "&quot;");

        return '<div class="product-card" onclick="openProductDetailById(\'' + p.id + '\')">' +
          '<div class="product-img-wrap" style="position:relative;">' +
            '<img src="' + cardImg + '" alt="' + pNameEsc + '" loading="lazy" onerror="if(typeof handleProductImageError===\'function\'){handleProductImageError(this,\'' + p.id + '\');}else{this.onerror=null;this.src=\'https://cdn.jsdelivr.net/gh/digimarketmmo/muabantaikhoanmmo-cdn@main/assets/images/default_product.png\';}" />' +
          '</div>' +
          '<div class="product-body">' +
            '<a href="/?prod=' + encodeURIComponent(p.id) + '&amp;view=viewProductDetail" class="product-title" onclick="if(!event.ctrlKey &amp;&amp; !event.metaKey &amp;&amp; event.button === 0){ event.preventDefault(); event.stopPropagation(); openProductDetailById(\'' + p.id + '\'); }" style="text-decoration:none; color:inherit; display:block;" title="' + pNameEsc + '">' + pNameEsc + '</a>' +
            '<div class="product-commission-tag"><i class="fa-solid fa-dollar-sign"></i> <span class="comm-text-full">HOA HỒNG: ' + commRate + '% (~' + commVal + ')</span><span class="comm-text-short">HH ' + commRate + '%</span></div>' +
            '<div class="product-footer-row">' +
              '<span class="product-price">' + priceDisplay + '</span>' +
              '<span class="product-rating-pill"><i class="fa-solid fa-star"></i> ' + (p.rating || "4.9") + '</span>' +
            '</div>' +
            '<div class="product-stock-line">' +
              '<span>Đã bán: ' + soldDisplay + '</span>' +
              '<span style="color:#94a3b8;">Kho: ' + stockVal + '</span>' +
            '</div>' +
          '</div>' +
        '</div>';
      }).join("");

      var pageInfoEl = document.getElementById("storeProdHeaderPaginationInfo");
      if (pageInfoEl) {
        var totalPages = Math.ceil(filtered.length / pageSize) || 1;
        pageInfoEl.innerText = "1/" + totalPages;
      }
      return;
    }
  }

  // Fallback: Nếu chưa có cache localStorage, lọc trực tiếp các thẻ HTML tĩnh đã render sẵn
  var cards = grid.querySelectorAll(".product-card");
  var matchCount = 0;
  for (var ci = 0; ci < cards.length; ci++) {
    var cardEl = cards[ci];
    var cTitle = (cardEl.querySelector(".product-title") ? cardEl.querySelector(".product-title").textContent : "").toLowerCase();
    var isMatch = (cat === "Tất cả") || earlyMatchProductCategory({ name: cTitle, category: cTitle }, cat);
    if (isMatch) {
      cardEl.style.display = "";
      matchCount++;
    } else {
      cardEl.style.display = "none";
    }
  }
}
window.renderEarlyCategoryProducts = renderEarlyCategoryProducts;

var filterCategory = window.filterCategory = window.switchCategory = function(cat) {
  window._pendingCategory = cat;
  if (typeof window._mmoFilterCategoryReal === 'function') {
    window._mmoFilterCategoryReal(cat);
  } else {
    renderEarlyCategoryProducts(cat);
  }
};

// Tự động áp dụng bộ lọc ngay từ mili-giây đầu tiên khi URL có ?category=...
try {
  var spEarly = new URLSearchParams(window.location.search);
  var earlyCat = spEarly.get('category');
  if (earlyCat) {
    window._pendingCategory = earlyCat;
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', function() {
        renderEarlyCategoryProducts(earlyCat);
      });
    } else {
      renderEarlyCategoryProducts(earlyCat);
    }
  }
} catch(e) {}
window.switchView = function(viewId) {
  if (typeof window._mmoSwitchViewReal === 'function') {
    window._mmoSwitchViewReal(viewId);
  } else {
    window._pendingView = viewId;
    var evs = document.getElementById("earlyViewRoutingStyle");
    if (evs) evs.remove();
    var allViews = ['viewStore', 'viewProductDetail', 'viewPreOrderDetail', 'viewBlog', 'viewBlogDetail', 'viewTools', 'viewProfile', 'viewDeposit', 'viewAdmin', 'viewThankYou', 'viewAllProducts', 'viewSitemap', 'viewTerms', 'viewPrivacy', 'viewWarranty', 'viewFaq'];
    for (var vi = 0; vi < allViews.length; vi++) {
      var el = document.getElementById(allViews[vi]);
      if (el) el.style.setProperty('display', (allViews[vi] === viewId ? 'block' : 'none'), 'important');
    }
  }
};
window.openProductDetailById = function(id) {
  if (typeof window._mmoOpenProductDetailReal === 'function') {
    window._mmoOpenProductDetailReal(id);
  } else {
    var cleanId = String(id || '').trim();
    var delList = [];
    try {
      var rawD = localStorage.getItem("mmo_deleted_product_ids");
      if (rawD) delList = JSON.parse(rawD);
    } catch(e) {}
    if (delList && Array.isArray(delList) && delList.indexOf(cleanId) !== -1) {
      window.switchView('viewStore');
      return;
    }
    window._pendingProductId = cleanId;
    window.switchView('viewProductDetail');
  }
};
window.handleLogout = window.logoutUser = function() {
  try { localStorage.removeItem("mmo_user"); } catch(e) {}
  try { sessionStorage.removeItem("mmo_user"); } catch(e) {}
  try { localStorage.setItem("mmo_current_view", "viewStore"); } catch(e) {}
  window.location.href = window.location.origin + "/";
};

/* EARLY PRE-ORDER va SSOT WALLET BALANCE ENGINE (Đảm bảo số dư ví và đặt trước luôn chạy tức thì 0ms) */
try {
  var rawEarlyU = localStorage.getItem("mmo_user");
  if (rawEarlyU) {
    var pEarlyU = JSON.parse(rawEarlyU);
    if (pEarlyU && pEarlyU.email) {
      var cleanEarlyEmail = (pEarlyU.email || "").toLowerCase().trim();
      if (cleanEarlyEmail === "digimarketmmo@gmail.com" && (pEarlyU.balance === 225120 || pEarlyU.balance === 225500)) {
        pEarlyU.balance = 127041;
        localStorage.setItem("mmo_user", JSON.stringify(pEarlyU));
      }
    }
  }
} catch(eEarlyBal) {}

window.getEffectiveWalletBalance = window.getEffectiveWalletBalance || function() {
  var bal = 0;
  try {
    var u = JSON.parse(localStorage.getItem("mmo_user") || "null");
    if (u && u.balance !== undefined && !isNaN(Number(u.balance))) bal = Math.max(0, Number(u.balance));
  } catch(e) {}
  return bal;
};

/* EARLY CENTRALIZED WALLET BALANCE UI SYNC ENGINE */
window.syncAllWalletBalanceUI = window.syncAllWalletBalanceUI || function(amount) {
  try {
    var num = (typeof amount === "number") ? amount : (Number(amount) || 0);
    var fmt = num.toLocaleString("vi-VN") + " \u0111";
    var elIds = ["headerWalletBalance", "profDisplayBalance", "profBalanceDisplay", "mobDrawerBalance"];
    for (var i = 0; i < elIds.length; i++) {
      var el = document.getElementById(elIds[i]);
      if (el) el.innerText = fmt;
    }
  } catch(e) {}
};

/* EARLY SYNC FOR PRE-ORDER MODAL (Đảm bảo số dư ví tự động nhảy số đúng 100% khi modal hiển thị) */
function syncPreOrderBalanceToModal() {
  try {
    var eff = (typeof window.getEffectiveWalletBalance === "function") ? window.getEffectiveWalletBalance() : 0;
    var bEl = document.getElementById("poModalUserBalance");
    if (bEl && eff > 0) {
      bEl.innerText = eff.toLocaleString("vi-VN") + " đ";
      var totEl = document.getElementById("poModalTotalPrice");
      var totVal = totEl ? (parseInt(String(totEl.innerText).replace(/[^0-9]/g, ""), 10) || 0) : 0;
      bEl.style.color = (eff >= totVal) ? "#10b981" : "#ef4444";
    }
  } catch(e) {}
}
document.addEventListener("DOMContentLoaded", function() {
  var poM = document.getElementById("preOrderModal");
  if (poM) {
    var obs = new MutationObserver(function() {
      if (poM.style.display !== "none" || poM.classList.contains("active")) {
        syncPreOrderBalanceToModal();
      }
    });
    obs.observe(poM, { attributes: true, attributeFilter: ["style", "class"] });
  }
});

/* INSTANT EARLY VIEW ROUTING ENGINE FOR GOOGLE BOT, CRAWLERS va DIRECT LINKS */
(function(){
  try {
    var h = (window.location.hash || '').replace('#', '').trim();
    var sp = new URLSearchParams(window.location.search);
    var v = sp.get('view') || '';

    var targetId = null;
    if (h === 'viewPrivacy' || h === 'privacy' || v === 'viewPrivacy' || (v === 'viewTerms' && (h === 'viewPrivacy' || h === 'privacy'))) {
      targetId = 'viewPrivacy';
    } else if (h === 'viewTerms' || h === 'terms' || v === 'viewTerms') {
      targetId = 'viewTerms';
    } else if (h === 'viewWarranty' || v === 'viewWarranty') {
      targetId = 'viewWarranty';
    } else if (h === 'viewSitemap' || v === 'viewSitemap') {
      targetId = 'viewSitemap';
    } else if (h === 'viewAllProducts' || v === 'viewAllProducts') {
      targetId = 'viewAllProducts';
    } else if (h === 'viewTools' || v === 'viewTools') {
      targetId = 'viewTools';
    } else if (h === 'viewBlog' || v === 'viewBlog') {
      targetId = 'viewBlog';
    } else if (h === 'viewAdmin' || v === 'viewAdmin' || h === 'admin' || v === 'admin') {
      try {
        var uRaw = localStorage.getItem("mmo_user");
        if (uRaw) {
          var uObj = JSON.parse(uRaw);
          if (uObj && (uObj.role === "Quản Trị Viên" || uObj.role === "ADMIN" || uObj.email === "manhdongvtc@gmail.com")) {
            targetId = 'viewAdmin';
          }
        }
      } catch(eU) {}
    }

    if (targetId) {
      document.addEventListener('DOMContentLoaded', function() {
        var allViews = ['viewStore', 'viewProductDetail', 'viewPreOrderDetail', 'viewBlog', 'viewBlogDetail', 'viewTools', 'viewProfile', 'viewDeposit', 'viewAdmin', 'viewThankYou', 'viewAllProducts', 'viewSitemap', 'viewTerms', 'viewPrivacy', 'viewWarranty', 'viewFaq'];
        allViews.forEach(function(viewName) {
          var el = document.getElementById(viewName);
          if (el) {
            if (viewName === targetId) {
              el.style.setProperty('display', 'block', 'important');
            } else {
              el.style.setProperty('display', 'none', 'important');
            }
          }
        });
        if (targetId === 'viewAdmin') {
          var nAdm = document.getElementById('navAdmin');
          if (nAdm) {
            nAdm.style.setProperty('display', 'flex', 'important');
            nAdm.classList.add('active');
          }
          var nStore = document.getElementById('navStore');
          if (nStore) nStore.classList.remove('active');
        }
      });
    }
  } catch(e) {}
})();
