head.script:
// Bắt tức thì mã ref tiếp thị liên kết ngay từ đầu tải trang
(function() {
  try {
    var p = new URLSearchParams(window.location.search);
    var r = p.get("ref");
    if (!r && window.location.hash.indexOf("ref=") !== -1) {
      var m = window.location.hash.match(/ref=([^&]+)/);
      if (m) r = decodeURIComponent(m[1]);
    }
    if (r) {
      var cr = String(r).trim().toLowerCase();
      localStorage.setItem("mmo_ref_code", cr);
      try { sessionStorage.setItem("mmo_ref_code", cr); } catch(e) {}
    }
  } catch(e) {}
})();

head.b:skin:
/* ==========================================================================
   MUABANTAIKHOANMMO.COM - CDN THEME ENGINE
   CSS CDN: https://cdn.jsdelivr.net/gh/digimarketmmo/muabantaikhoanmmo-cdn@v6.4.8/theme.min.css?v=6.4.7
   JS CDN:  https://cdn.jsdelivr.net/gh/digimarketmmo/muabantaikhoanmmo-cdn@v6.4.8/bundle.min.js?v=6.4.7
   ========================================================================== */
body { margin: 0; padding: 0; background: #070a12; color: #cbd5e1; font-family: 'Plus Jakarta Sans', sans-serif; }

/* CHỐNG TRÀN TRANG TOÀN BỘ WEBSITE MÀ KHÔNG LÀM HỎNG STICKY SIDEBARS */
html, body {
  overflow-x: clip !important;
  max-width: 100vw !important;
}

*, *::before, *::after {
  box-sizing: border-box !important;
}

/* ĐẢM BẢO TẤT CẢ CONTAINER CHA ĐỀU OVERFLOW: VISIBLE ĐỂ POSITION: STICKY HOẠT ĐỘNG 100% */
.home-container,
.container,
.all-products-page-container,
.blog-page-container,
#viewStore,
#viewAllProducts {
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  overflow-x: clip !important;
}

/* THU NHỎ TRANG XEM SẢN PHẨM, ĐỂ LẠI KHOẢNG TRỐNG ĐEN HAI BÊN TRÁI PHẢI */
#viewProductDetail {
  width: 88% !important;
  max-width: 88% !important;
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
  box-sizing: border-box !important;
  overflow: visible !important;
}

/* TRANG XEM BÀI VIẾT BLOG: CỠ CHUẨN TĂNG THÊM 5% (1250PX, 95% WIDTH) CÂN ĐỐI TỰ NHIÊN */
.article-page-container,
#viewBlogDetail {
  width: 95% !important;
  max-width: 1250px !important;
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
  box-sizing: border-box !important;
  overflow: visible !important;
}

/* FIX MOBILE SCROLL: CHO PHÉP VUỐT DỌC VÀ VUỐT NGANG MƯỢT MÀ TRÊN ĐIỆN THOẠI KHÔNG BỊ ĐƠ */
.adm-api-table-wrapper,
div:has(> #admApiAlertsTable),
div:has(> table.admin-table),
div:has(> table.adm-table) {
  overflow-x: auto !important;
  -webkit-overflow-scrolling: touch !important;
  touch-action: pan-x pan-y !important;
  overscroll-behavior-x: contain !important;
  overscroll-behavior-y: auto !important;
}
#tabAdmApiSources {
  touch-action: auto !important;
  overflow: visible !important;
}

/* TỐI ƯU HÓA ĐỘ PHẢN HỒI CLICK / CHẠM 0MS - LOẠI BỎ ĐỘ TRỄ 300MS &amp; CHỐNG LAG */
a, button, [onclick], .nav-link, .product-card, .blog-item, .category-card, .sidebar-blog-item, .detail-tab-btn, .variant-pill-option, .modal-close-btn, .blog-card-full {
  touch-action: manipulation !important;
  -webkit-tap-highlight-color: transparent !important;
  cursor: pointer !important;
}

.separator img,
.article-main-content img,
#viewBlogDetail img,
#aiEditorContent img {
  max-width: 100% !important;
  height: auto !important;
  border-radius: 10px;
  image-rendering: -webkit-optimize-contrast;
  image-rendering: crisp-edges;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.25);
  margin: 18px auto !important;
  display: block !important;
}

@media (max-width: 768px) {
  .article-page-container,
  #viewBlogDetail {
    width: 100% !important;
    max-width: 100% !important;
    padding: 0 10px !important;
    margin: 12px auto 40px !important;
  }
}

.home-container {
  padding: 16px 20px !important;
}

/* ==========================================================================
   1. THANH BÊN TRANG CHỦ (VIEWSTORE) - CỐ ĐỊNH TRƯỢT THEO CUỘN MƯỢT MÀ
   ========================================================================== */
.home-main-layout {
  display: grid !important;
  grid-template-columns: 280px minmax(0, 1fr) 280px !important;
  gap: 16px !important;
  width: 100% !important;
  box-sizing: border-box !important;
  align-items: start !important;
  overflow: visible !important;
}

.home-sidebar-left,
