/* ==========================================================================
   3. THANH BÊN BÀI VIẾT (VIEWBLOGDETAIL) &amp; BỘ LỌC (VIEWALLPRODUCTS)
   ========================================================================== */
.article-layout-grid {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) 320px !important;
  gap: 20px !important;
  align-items: start !important;
  overflow: visible !important;
}

.all-products-layout {
