html.script:
//
(function() {
  try {
    var h = (window.location.hostname || '').toLowerCase();
    if (h.indexOf('taphoammo.ink') !== -1 || h.indexOf('taphoammo') !== -1) {
      window._CURRENT_SITE_BRAND = 'taphoammo';
      document.addEventListener('DOMContentLoaded', function() {
        var hEl = document.getElementById('headerSiteName');
        if (hEl) hEl.innerText = 'TAPHOAMMO.INK';
        var fEl = document.getElementById('footerSiteName') || document.querySelector('.footer-col-1 .logo-text div');
        if (fEl) fEl.innerText = 'TAPHOAMMO.INK';
        var tagEl = document.querySelector('.header-inner .logo-text span, .logo .logo-text span');
        if (tagEl) tagEl.innerHTML = 'Sàn Sản Phẩm Số &amp; Dịch Vụ MMO';
        var cEl = document.querySelector('.footer-bottom-bar > div:first-child');
        if (cEl) cEl.innerHTML = '&copy; 2026 TAPHOAMMO.INK. All rights reserved.';
        var mTrack = document.getElementById('homeMarqueeTrack');
        if (mTrack) {
          var mItems = mTrack.querySelectorAll('.marquee-item');
          mItems.forEach(function(item) {
            item.innerHTML = '<i class="fa-solid fa-bullhorn" style="color:#38bdf8; margin-right:8px; font-size:0.8rem;"></i>🎉 Chào mừng bạn đến với TAPHOAMMO.INK - Hệ thống mua bán tài khoản MMO, Gmail, TikTok, Facebook, Rom &amp; Tools uy tín số 1. Nạp tiền tự động qua SePay 24/7. Hỗ trợ bảo hành 1-đổi-1 siêu tốc!';
          });
        }
      });
    }
  } catch(e) {}
})();
//

div.script:
//
/* EARLY USER AUTH & BALANCE HYDRATION (v6.3.3: Hiển thị đúng số dư & avatar 0ms, không nhấp nháy 0 đ/Đăng Nhập 1 giây) */
(function() {
  try {
    var rawU = localStorage.getItem("mmo_user");
    if (rawU) {
      var u = JSON.parse(rawU);
      if (u && u.email) {
        var bal = (u.balance !== undefined && !isNaN(Number(u.balance))) ? Number(u.balance) : 0;
        var bEl = document.getElementById("headerWalletBalance");
        if (bEl) bEl.innerText = bal.toLocaleString("vi-VN") + " đ";
        var aEl = document.getElementById("authArea");
        if (aEl) {
          var name = u.name || u.email.split("@")[0];
          var avatar = u.avatar || ("https://api.dicebear.com/7.x/bottts/svg?seed=" + encodeURIComponent(u.email));
          aEl.innerHTML = '<div class="header-user-badge" onclick="switchView(\'viewProfile\')" style="cursor:pointer; display:flex; align-items:center; gap:8px; background:rgba(255,255,255,0.06); padding:4px 10px; border-radius:20px; border:1px solid rgba(255,255,255,0.1);"><img src="' + avatar + '" style="width:24px; height:24px; border-radius:50%; object-fit:cover;" alt="Avatar"/><span class="header-user-name" style="font-weight:600; font-size:0.85rem; color:#f8fafc; max-width:120px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">' + name + '</span></div>';
        }
        if (u.role === "Quản Trị Viên" || u.role === "ADMIN" || u.email === "manhdongvtc@gmail.com" || u.email === "digimarketmmo@gmail.com") {
          var adm = document.getElementById("navAdmin");
          if (adm) adm.style.setProperty("display", "flex", "important");
        }
      }
    }
    if (window._earlyTargetView && window._earlyTargetView !== 'viewStore') {
      var nStore = document.getElementById('navStore');
      if (nStore) nStore.classList.remove('active');
      var navMap = {
        'viewAllProducts': 'navProducts',
        'viewBlog': 'navBlog',
        'viewTools': 'navTools',
        'viewProfile': 'navProfile',
        'viewAdmin': 'navAdmin'
      };
      var targetNavId = navMap[window._earlyTargetView];
      if (targetNavId) {
        var tNav = document.getElementById(targetNavId);
        if (tNav) tNav.classList.add('active');
      }
    }
  } catch(e) {}
})();
