body.script:
//
// =========================================================================
// AI SEO PRODUCT DESCRIPTION WRITER ENGINE (v5.9.9 - NATIVE INLINE)
// =========================================================================
function openAdmAiWriterModal() {
  try {
    var modal = document.getElementById("admAiWriterModal");
    if (!modal) {
      alert("Không tìm thấy modal AI Writer trên trang!");
      return;
    }

    var prodNameInput = document.getElementById("admProdName");
    var prodCatSelect = document.getElementById("admProdCategory");
    var aiProdName = document.getElementById("aiWriterProdName");
    var aiKeywords = document.getElementById("aiWriterKeywords");
    var aiCategory = document.getElementById("aiWriterCategory");
    var aiStatusBox = document.getElementById("aiWriterStatusBox");

    var currentName = prodNameInput ? prodNameInput.value.trim() : "";
    var currentCat = prodCatSelect ? prodCatSelect.value.trim() : "Tài Khoản MMO";

    if (aiProdName) aiProdName.value = currentName || "Tài Khoản MMO Chất Lượng Cao";
    if (aiCategory) aiCategory.value = currentCat;

    if (aiKeywords) {
      var kw = currentName;
      if (currentName) {
        kw = currentName.toLowerCase()
          .replace(/[-\/]/g, ' ')
          .replace(/\s+/g, ' ')
          .trim();
      }
      aiKeywords.value = kw || "mua tài khoản mmo uy tín, shop tài khoản giá rẻ";
    }

    if (aiStatusBox) {
      aiStatusBox.style.display = "none";
      aiStatusBox.innerHTML = "";
    }

    var btnRun = document.getElementById("btnRunAiWriter");
    if (btnRun) {
      btnRun.disabled = false;
      btnRun.innerHTML = '<i class="fa-solid fa-wand-magic-sparkles"></i> 🚀 BẮT ĐẦU VIẾT BÀI BẰNG AI';
    }

    modal.style.display = "flex";
    modal.style.zIndex = "999999999";
  } catch (err) {
    console.error("Error opening AI Writer modal:", err);
    alert("Lỗi khi mở giao diện AI Writer: " + err.message);
  }
}
window.openAdmAiWriterModal = openAdmAiWriterModal;

function closeAdmAiWriterModal() {
  var modal = document.getElementById("admAiWriterModal");
  if (modal) modal.style.display = "none";
}
window.closeAdmAiWriterModal = closeAdmAiWriterModal;

async function executeAiWriter() {
  var aiProdName = document.getElementById("aiWriterProdName");
  var aiKeywords = document.getElementById("aiWriterKeywords");
  var aiCategory = document.getElementById("aiWriterCategory");
  var aiLength = document.getElementById("aiWriterLength");
  var aiTone = document.getElementById("aiWriterTone");
  var aiStatusBox = document.getElementById("aiWriterStatusBox");
  var btnRun = document.getElementById("btnRunAiWriter");

  var prodName = aiProdName ? aiProdName.value.trim() : "";
  if (!prodName) {
    alert("Vui lòng nhập tên sản phẩm để AI viết bài chuẩn SEO!");
    if (aiProdName) aiProdName.focus();
    return;
  }

  var keywords = aiKeywords ? aiKeywords.value.trim() : prodName;
  var category = aiCategory ? aiCategory.value.trim() : "Tài Khoản MMO";
  var targetLength = aiLength ? aiLength.value : "standard";
  var tone = aiTone ? aiTone.value : "mmo_pro";

  if (btnRun) {
    btnRun.disabled = true;
    btnRun.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Đang Viết Bài Chuẩn SEO...';
  }

  if (aiStatusBox) {
    aiStatusBox.style.display = "block";
    aiStatusBox.innerHTML = '<div style="background:rgba(139,92,246,0.15); border:1px solid rgba(139,92,246,0.4); border-radius:8px; padding:12px; margin-top:12px; text-align:left;">' +
      '<div style="display:flex; align-items:center; gap:8px; color:#c084fc; font-weight:700; font-size:0.88rem; margin-bottom:6px;">' +
      '<i class="fa-solid fa-spinner fa-spin"></i> <span id="aiStepText">Đang phân tích từ khóa và cấu trúc bài viết...</span>' +
      '</div>' +
      '<div style="font-size:0.75rem; color:#94a3b8;" id="aiDetailText">Hệ thống đang khởi tạo dàn bài H2, H3, FAQ và nội dung chuyên sâu MMO (500 - 1000 từ)...</div>' +
      '</div>';
  }

  var stepTimer1 = setTimeout(function() {
    var t = document.getElementById("aiStepText");
    var d = document.getElementById("aiDetailText");
    if (t) t.textContent = "📐 Đang tối ưu thẻ H2, H3, bảng thông số & hướng dẫn chống checkpoint...";
    if (d) d.textContent = "Đang tích hợp từ khóa LSI và mật độ chuẩn On-Page Google...";
  }, 1200);

  var stepTimer2 = setTimeout(function() {
    var t = document.getElementById("aiStepText");
    var d = document.getElementById("aiDetailText");
    if (t) t.textContent = "✍️ Đang hoàn thiện các mục FAQ & cam kết bảo hành 1 đổi 1...";
    if (d) d.textContent = "Đang kiểm tra độ dài bài viết đạt chuẩn 500 - 1000 từ...";
  }, 2500);

  try {
    var adminSec = localStorage.getItem("mmo_admin_secret") || "";
    var res = await fetch("https://mmo-shop-api.muabantaikhoanmmo.workers.dev/api/admin/ai-write-description", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-admin-secret": adminSec
      },
      body: JSON.stringify({
        productName: prodName,
        category: category,
        keywords: keywords,
        targetLength: targetLength,
        tone: tone
      })
    });

    clearTimeout(stepTimer1);
    clearTimeout(stepTimer2);

    var data = await res.json();
    if (!res.ok || !data.success) {
      throw new Error(data.message || "Lỗi không xác định từ máy chủ AI");
    }

    var visual = document.getElementById("admProdDescVisual");
    var raw = document.getElementById("admProdDesc");

    if (visual) visual.innerHTML = data.html;
    if (raw) raw.value = data.html;

    if (typeof syncAdmDescFromVisual === "function") {
      syncAdmDescFromVisual();
    }

    closeAdmAiWriterModal();

    alert("✨ AI đã tạo bài viết chuẩn SEO thành công (~" + (data.wordCount || "1000") + " từ)!\n\nNội dung đã được điền vào trình soạn thảo bài viết. Bạn có thể kiểm tra và bấm 'LƯU SẢN PHẨM'.");

    if (visual) {
      visual.scrollIntoView({ behavior: "smooth", block: "center" });
      visual.focus();
    }
  } catch (err) {
    clearTimeout(stepTimer1);
    clearTimeout(stepTimer2);
    alert("Không thể viết bài bằng AI: " + (err.message || String(err)));
    if (aiStatusBox) {
      aiStatusBox.innerHTML = '<div style="background:rgba(239,68,68,0.15); border:1px solid rgba(239,68,68,0.4); border-radius:8px; padding:10px; margin-top:12px; color:#f87171; font-size:0.8rem;">' +
        '<i class="fa-solid fa-triangle-exclamation"></i> Lỗi: ' + (err.message || String(err)) +
        '</div>';
    }
  } finally {
    if (btnRun) {
      btnRun.disabled = false;
      btnRun.innerHTML = '<i class="fa-solid fa-wand-magic-sparkles"></i> 🚀 BẮT ĐẦU VIẾT BÀI BẰNG AI';
    }
  }
}
window.executeAiWriter = executeAiWriter;

// =========================================================================
// PRODUCT DETAIL ARTICLE & TOC RENDER ENGINE (v5.9.9 - NATIVE MULTILINE H2, H3, H4)
// =========================================================================
function scrollToDetailSection(sectionId) {
  if (!sectionId) return;
  var wrap = document.getElementById("dtlDescWrapper");
  var txt = document.getElementById("dtlDescToggleText");
  var icon = document.getElementById("dtlDescToggleIcon");
  if (wrap && wrap.classList.contains("collapsed")) {
    wrap.classList.remove("collapsed");
    if (txt) txt.textContent = "Thu gọn";
    if (icon) icon.className = "fa-solid fa-chevron-up";
  }

  setTimeout(function() {
    var target = document.getElementById(sectionId);
    if (target) {
      var yOffset = -90;
      var y = target.getBoundingClientRect().top + window.pageYOffset + yOffset;
      window.scrollTo({ top: Math.max(0, y), behavior: "smooth" });
      target.style.transition = "all 0.3s ease";
      var oldColor = target.style.color;
      target.style.color = "#38bdf8";
      target.style.transform = "translateX(6px)";
      setTimeout(function() {
        target.style.color = oldColor;
        target.style.transform = "none";
      }, 1200);
    }
  }, 60);
}
window.scrollToDetailSection = scrollToDetailSection;

function renderProductDetailArticle(p, customDesc) {
  if (!p) return;
  var name = (p.name || "Sản Phẩm MMO").trim();
  var cat = (p.category || "Tài nguyên MMO").trim();
  var warranty = (p.warranty || "Bảo Hành 1 Đổi 1").trim();
  var custom = (typeof cleanAndNormalizeHtml === "function") ? cleanAndNormalizeHtml(typeof customDesc === "string" ? customDesc : (p.description || "")) : (typeof customDesc === "string" ? customDesc : (p.description || ""));
  var esc = (typeof escapeHtml === "function") ? escapeHtml : function(str) {
    return String(str).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  };

  var hasCustomHeadings = /<h[2-4]\b[^>]*>/i.test(custom);
  var finalArticleHtml = "";
  var tocItems = [];

  if (hasCustomHeadings) {
    var hCount = 0;
    var h2Idx = 0;
    var h3Idx = 0;
    var h4Idx = 0;

    finalArticleHtml = custom.replace(/<h([2-4])\b([^>]*)>([\s\S]*?)<\/h\1>/gi, function(match, level, attrs, innerText) {
      hCount++;
      var secId = "dtl-custom-sec-" + hCount;
      var cleanText = innerText.replace(/<[^>]*>/g, "").replace(/\s+/g, " ").trim();
      var numStr = "";
      if (level === "2") {
        h2Idx++;
        h3Idx = 0;
        h4Idx = 0;
        numStr = String(h2Idx);
      } else if (level === "3") {
        h3Idx++;
        h4Idx = 0;
        numStr = (h2Idx || 1) + "." + h3Idx;
      } else {
        h4Idx++;
        numStr = (h2Idx || 1) + "." + (h3Idx || 1) + "." + h4Idx;
      }

      var displayTitle = cleanText;
      var displayNum = numStr;
      var startsWithNumber = /^(\d+(\.\d+)*)\s*[\.\-:]?\s*/.exec(cleanText);
      if (startsWithNumber) {
        displayNum = startsWithNumber[1];
        displayTitle = cleanText.substring(startsWithNumber[0].length).trim();
      }

      tocItems.push({
        id: secId,
        level: level === "2" ? 1 : (level === "3" ? 2 : 3),
        num: displayNum,
        title: displayTitle || (level === "2" ? "Mục " + numStr : (level === "3" ? "Chi tiết " + numStr : "Mục con " + numStr))
      });
      return '<h' + level + ' id="' + secId + '" class="dtl-article-h' + level + '" ' + attrs + '>' + innerText + '</h' + level + '>';
    });
  } else if (custom && custom.length > 50) {
    var formattedBody = (/<[a-z][\s\S]*>/i.test(custom)) ? custom : custom.replace(/\n/g, "<br>");
    tocItems = [
      { id: "dtl-sec-main", level: 1, num: "1", title: name },
      { id: "dtl-sec-warranty", level: 1, num: "2", title: "Chính Sách Bảo Hành & Cam Kết Đổi Trả" }
    ];
    finalArticleHtml = '<div id="dtl-sec-main" style="color:#cbd5e1; line-height:1.75; font-size:0.9rem; margin-bottom:16px;">' + formattedBody + '</div>' +
      '<h2 id="dtl-sec-warranty" class="dtl-article-h2">Chính Sách Bảo Hành &amp; Cam Kết Đổi Trả</h2>' +
      '<p class="dtl-article-p">Sàn <strong>MUABANTAIKHOANMMO</strong> áp dụng chính sách <strong>' + esc(warranty) + '</strong> minh bạch và rõ ràng. Mọi vấn đề lỗi đăng nhập lần đầu hoặc lỗi xuất phát từ hệ thống đều được hỗ trợ xử lý 1:1 siêu tốc qua đội ngũ CSKH trực tuyến 24/7 trên kênh Zalo và Telegram.</p>';
  } else {
    tocItems = [
      { id: "dtl-sec-1", level: 1, num: "1", title: "Mua " + name + " Giá Rẻ Tại Muabantaikhoanmmo.com" },
      { id: "dtl-sec-2", level: 1, num: "2", title: name + " Là Gì?" },
      { id: "dtl-sec-3", level: 1, num: "3", title: "Ưu Điểm Khi Sử Dụng " + name },
      { id: "dtl-sec-4", level: 1, num: "4", title: "Hướng Dẫn Sử Dụng &amp; Đăng Nhập An Toàn" },
      { id: "dtl-sec-5", level: 1, num: "5", title: "Chính Sách Bảo Hành &amp; Cam Kết Đổi Trả" }
    ];
    finalArticleHtml = '<h2 id="dtl-sec-1" class="dtl-article-h2">Mua ' + esc(name) + ' Giá Rẻ Tại Muabantaikhoanmmo.com</h2>' +
      '<p class="dtl-article-p">Nếu bạn đang cần một sản phẩm <strong>' + esc(name) + '</strong> chất lượng cao, dễ sử dụng, kết nối ổn định và an toàn để phục vụ công việc kiếm tiền online (MMO), chạy quảng cáo hoặc sử dụng thường ngày, <strong>' + esc(name) + '</strong> là một lựa chọn rất đáng cân nhắc.</p>' +
      '<h2 id="dtl-sec-2" class="dtl-article-h2">' + esc(name) + ' Là Gì?</h2>' +
      '<p class="dtl-article-p"><strong>' + esc(name) + '</strong> là giải pháp thuộc danh mục <strong>' + esc(cat) + '</strong> được đông đảo cộng đồng kiếm tiền online tin dùng.</p>' +
      '<h2 id="dtl-sec-3" class="dtl-article-h2">Ưu Điểm Khi Sử Dụng ' + esc(name) + '</h2>' +
      '<p class="dtl-article-p">Sản phẩm có độ trust cao, ổn định và kháng checkpoint mạnh mẽ.</p>' +
      '<h2 id="dtl-sec-4" class="dtl-article-h2">Hướng Dẫn Sử Dụng &amp; Đăng Nhập An Toàn</h2>' +
      '<p class="dtl-article-p">Đăng nhập tài khoản qua proxy sạch hoặc mạng cá nhân an toàn.</p>' +
      '<h2 id="dtl-sec-5" class="dtl-article-h2">Chính Sách Bảo Hành &amp; Cam Kết Đổi Trả</h2>' +
      '<p class="dtl-article-p">Sàn MUABANTAIKHOANMMO áp dụng chính sách bảo hành 1 đổi 1 minh bạch và rõ ràng.</p>';
  }

  var tocNav = document.getElementById("dtlTocNav");
  var tocBox = document.getElementById("dtlTocBox");
  if (tocNav) {
    tocNav.innerHTML = tocItems.map(function(item) {
      var levelClass = item.level === 1 ? "dtl-toc-level-1" : (item.level === 2 ? "dtl-toc-level-2" : "dtl-toc-level-3");
      return '<a class="dtl-toc-item ' + levelClass + '" onclick="scrollToDetailSection(\'' + item.id + '\')">' +
        '<span class="dtl-toc-num">' + item.num + '</span> ' + esc(item.title) +
      '</a>';
    }).join("");
  }

  if (tocBox) {
    if (tocItems.length === 0) {
      tocBox.style.display = "none";
    } else {
      tocBox.style.display = "block";
      tocBox.classList.add("collapsed");
    }
  }

  var dtlDesc = document.getElementById("dtlFullDesc");
  if (dtlDesc) {
    dtlDesc.innerHTML = finalArticleHtml;
  }

  var wrap = document.getElementById("dtlDescWrapper");
  var txt = document.getElementById("dtlDescToggleText");
  var icon = document.getElementById("dtlDescToggleIcon");
  var btnWrap = document.getElementById("dtlDescToggleWrap");
  if (wrap) wrap.classList.add("collapsed");
  if (txt) txt.textContent = "Xem thêm";
  if (icon) icon.className = "fa-solid fa-chevron-down";
  if (btnWrap) btnWrap.style.display = "block";
}
window.renderProductDetailArticle = renderProductDetailArticle;
