body.script:
//
(function() {
  window.getBackendApiUrl = function() {
    return "https://script.google.com/macros/s/AKfycbylo1VU2SibsBmrxeCmWDCSm521HnW-Cd3vnmaKqJevPa4HPy4A_LyrQJ54T6BzgBI6Dg/exec";
  };

  // Tự động chuyển đổi toàn bộ nhãn 'Hết hàng' sang 'Đặt trước' (Chống kẹt cache 100%)
  function convertOutOfStockToPreOrder() {
    try {
      var spans = document.querySelectorAll(".product-card span, .search-drop-stock span, #dtlStock span");
      for (var i = 0; i < spans.length; i++) {
        var s = spans[i];
        var txt = s.textContent ? s.textContent.trim() : "";
        if (txt === "Hết hàng" || txt === "Hết Hàng") {
          s.innerHTML = '<i class="fa-solid fa-clock"></i> Đặt trước';
          s.style.color = "#f59e0b";
          if (s.style.position === "absolute" || (s.style.background && (s.style.background.indexOf("ef4444") !== -1 || s.style.background.indexOf("239") !== -1))) {
            s.style.background = "linear-gradient(135deg, #f59e0b, #ea580c)";
            s.style.color = "#ffffff";
          }
        }
      }
    } catch(e) {}
  }
  document.addEventListener("DOMContentLoaded", convertOutOfStockToPreOrder);
  window.addEventListener("load", convertOutOfStockToPreOrder);

  // Tự Động Đồng Bộ va Cập Nhật Mạng Lưới Đa Blog Realtime (v5.3.4)
  var CURRENT_THEME_CODE_VERSION = "6.3.1";
  function checkAndApplyNetworkUpdate() {
    try {
      if (window._mmoThemeHotReloadInProgress || (window._lastThemeHotReloadTime && Date.now() - window._lastThemeHotReloadTime < 300000)) return;
      fetch("https://mmo-shop-api.muabantaikhoanmmo.workers.dev/api/v1/version?t=" + Date.now(), {
        cache: "no-store",
        headers: { "Pragma": "no-cache", "Cache-Control": "no-cache" }
      })
      .then(function(res) { return res.json(); })
      .then(function(data) {
        function isVerHigher(newV, curV) {
          var p1 = (newV || '').split('.').map(Number);
          var p2 = (curV || '').split('.').map(Number);
          for (var i = 0; i < Math.max(p1.length, p2.length); i++) {
            var num1 = p1[i] || 0, num2 = p2[i] || 0;
            if (num1 > num2) return true;
            if (num1 < num2) return false;
          }
          return false;
        }
        if (data && data.version && isVerHigher(data.version, CURRENT_THEME_CODE_VERSION)) {
          window._mmoThemeHotReloadInProgress = true;
          window._lastThemeHotReloadTime = Date.now();
          console.log("[MMO Network Update] Phát hiện phiên bản mới: v" + data.version + " (Bản hiện tại: v" + CURRENT_THEME_CODE_VERSION + ")");
          localStorage.setItem("mmo_network_code_version", data.version);

          // Tự động cập nhật CSS
          var cssEl = document.getElementById("mmoCdnThemeCss");
          var newCssUrl = (data.theme_url || "https://cdn.jsdelivr.net/gh/digimarketmmo/muabantaikhoanmmo-cdn@v6.4.8/theme.min.css?v=6.4.7");
          if (cssEl) cssEl.href = newCssUrl;

          // Mã nguồn chính thức đã được tải an toàn từ CDN v5.7.9
        }
      }).catch(function(e) {});
    } catch(err) {}
  }
  setTimeout(checkAndApplyNetworkUpdate, 300);
  setInterval(checkAndApplyNetworkUpdate, 300000);
  window.addEventListener("focus", checkAndApplyNetworkUpdate);

  // Khai báo trực tiếp: Đảm bảo 100% nút "So sánh nguồn" hoạt động tức thì kể cả khi kẹt cache CDN
  window.openSourceCompareModal = window.openSourceCompareModal || function(prodId) {
    var modal = document.getElementById("admCompareSourcesModal");
    if (modal) {
      modal.style.display = "flex";
      modal.style.zIndex = "999999";
      var card = modal.querySelector(".modal-card");
      if (card) { card.style.maxWidth = "1420px"; card.style.width = "96%"; card.style.maxHeight = "92vh"; }
    }
  };

  window.openCompareModalFromCurrentEdit = function() {
    var inp = document.getElementById("admProdId");
    var nameInp = document.getElementById("admProdName");
    var prodId = inp ? inp.value.trim() : "";
    var nameVal = nameInp ? nameInp.value.trim() : "";
    if (typeof openSourceCompareModal === "function") {
      openSourceCompareModal(prodId || nameVal || "NEW_PRODUCT");
    } else {
      var modal = document.getElementById("admCompareSourcesModal");
      if (modal) {
        modal.style.display = "flex";
        modal.style.zIndex = "999999";
        var card = modal.querySelector(".modal-card");
        if (card) { card.style.maxWidth = "1420px"; card.style.width = "96%"; card.style.maxHeight = "92vh"; }
      }
    }
  };

  window.closeSourceCompareModal = function() {
    var modal = document.getElementById("admCompareSourcesModal");
    if (modal) modal.style.display = "none";
  };

  window.switchSourceByRegistry = function(regKey, btnEl) {
    if (typeof window.applySwitchSource === "function") {
      var item = (window._compareRegistry && regKey) ? window._compareRegistry[regKey] : null;
      if (!item && btnEl) {
        var p = btnEl.getAttribute('data-provider');
        var sid = btnEl.getAttribute('data-source-id');
        if (p && sid) {
          item = {
            provider: p,
            sourceProdId: sid,
            sourcePrice: Number(btnEl.getAttribute('data-price') || 0),
            sourceStock: Number(btnEl.getAttribute('data-stock') || 0),
            sourceProdName: btnEl.getAttribute('data-name') || ""
          };
        }
      }
      if (item) {
        window.applySwitchSource(
          window.currentCompareProdId,
          item.provider,
          item.sourceProdId,
          item.sourcePrice,
          item.sourceStock,
          item.sourceProdName
        );
      }
    }
  };

  // Khai báo tức thì switchAuthTab trực tiếp trong Theme (Đảm bảo 100% không bị kẹt cache CDN)
  window.switchAuthTab = function(tab) {
    var btnLogin = document.getElementById("tabBtnLogin");
    var btnRegister = document.getElementById("tabBtnRegister");
    var formLogin = document.getElementById("formLoginBlock");
    var formRegister = document.getElementById("formRegisterBlock");
    var formForgot = document.getElementById("formForgotBlock");
    var googleSection = document.getElementById("googleAuthSection");
    var title = document.getElementById("authModalTitle");

    if (tab === "forgot") {
      if (formLogin) formLogin.style.display = "none";
      if (formRegister) formRegister.style.display = "none";
      if (formForgot) formForgot.style.display = "flex";
      if (googleSection) googleSection.style.display = "none";
      if (btnLogin) {
        btnLogin.style.background = "transparent";
        btnLogin.style.color = "#94a3b8";
        btnLogin.style.fontWeight = "500";
      }
      if (btnRegister) {
        btnRegister.style.background = "transparent";
        btnRegister.style.color = "#94a3b8";
        btnRegister.style.fontWeight = "500";
      }
      if (title) title.innerHTML = "<i class='fa-solid fa-key' style='color:#38bdf8;'></i> Khôi Phục Mật Khẩu";

      try {
        var loginEmailEl = document.getElementById("loginEmailInput");
        var curLoginEmail = loginEmailEl && loginEmailEl.value ? String(loginEmailEl.value).trim() : "";
        var forgotEmailInp = document.getElementById("forgotEmailInput");
        if (curLoginEmail && forgotEmailInp && !forgotEmailInp.value) {
          forgotEmailInp.value = curLoginEmail;
        }
      } catch(e) {}
      var s1 = document.getElementById("forgotStep1");
      var s2 = document.getElementById("forgotStep2");
      if (s1) s1.style.display = "block";
      if (s2) s2.style.display = "none";
      var otpInp = document.getElementById("forgotOtpInput");
      if (otpInp) otpInp.value = "";
    } else if (tab === "register") {
      if (formLogin) formLogin.style.display = "none";
      if (formRegister) formRegister.style.display = "flex";
      if (formForgot) formForgot.style.display = "none";
      if (googleSection) googleSection.style.display = "block";
      try {
        var savedRef = (localStorage.getItem("mmo_ref_code") || sessionStorage.getItem("mmo_ref_code") || "").trim();
        var refNoticeEl = document.getElementById("regRefNotice");
        var refTextEl = document.getElementById("regRefCodeText");
        if (refNoticeEl && savedRef) {
          refNoticeEl.style.display = "flex";
          if (refTextEl) refTextEl.innerText = "@" + savedRef;
        }
      } catch(e) {}
      if (btnLogin) {
        btnLogin.style.background = "transparent";
        btnLogin.style.color = "#94a3b8";
        btnLogin.style.fontWeight = "500";
      }
      if (btnRegister) {
        btnRegister.style.background = "#3b82f6";
        btnRegister.style.color = "#ffffff";
        btnRegister.style.fontWeight = "700";
      }
      if (title) title.innerHTML = "<i class='fa-solid fa-user-plus' style='color:#3b82f6;'></i> Đăng Ký Tài Khoản";
    } else {
      if (formLogin) formLogin.style.display = "flex";
      if (formRegister) formRegister.style.display = "none";
      if (formForgot) formForgot.style.display = "none";
      if (googleSection) googleSection.style.display = "block";
      if (btnLogin) {
        btnLogin.style.background = "#10b981";
        btnLogin.style.color = "#ffffff";
        btnLogin.style.fontWeight = "700";
      }
      if (btnRegister) {
        btnRegister.style.background = "transparent";
        btnRegister.style.color = "#94a3b8";
        btnRegister.style.fontWeight = "500";
      }
      if (title) title.innerHTML = "<i class='fa-solid fa-user-shield green'></i> Đăng Nhập Hệ Thống";
    }
  };

  var forgotCooldownTimer = null;
  var forgotCooldownSec = 0;

  window.handleResendForgotOtp = function() {
    if (forgotCooldownSec > 0) {
      if (typeof showToast === "function") showToast("Vui lòng chờ " + forgotCooldownSec + " giây để gửi lại mã!", "warning");
      return;
    }
    window.handleRequestPasswordReset(true);
  };

  window.startForgotCooldown = function(seconds) {
    forgotCooldownSec = seconds || 60;
    var btn = document.getElementById("btnResendForgotOtp");
    if (forgotCooldownTimer) clearInterval(forgotCooldownTimer);
    var updateBtn = function() {
      if (btn) {
        if (forgotCooldownSec > 0) {
          btn.disabled = true;
          btn.style.opacity = "0.6";
          btn.style.cursor = "not-allowed";
          btn.textContent = "Gửi lại (" + forgotCooldownSec + "s)";
        } else {
          btn.disabled = false;
          btn.style.opacity = "1";
          btn.style.cursor = "pointer";
          btn.textContent = "Gửi lại mã";
        }
      }
    };
    updateBtn();
    forgotCooldownTimer = setInterval(function() {
      forgotCooldownSec--;
      updateBtn();
      if (forgotCooldownSec <= 0) {
        clearInterval(forgotCooldownTimer);
        forgotCooldownTimer = null;
      }
    }, 1000);
  };

  window.handleRequestPasswordReset = async function(isResend) {
    var emailInp = document.getElementById("forgotEmailInput");
    var email = (sessionStorage.getItem("mmo_forgot_email") || (emailInp ? emailInp.value : "")).trim().toLowerCase();
    if (!email || !email.includes("@")) {
      if (typeof showToast === "function") showToast("Vui lòng nhập địa chỉ email hợp lệ!", "warning");
      return;
    }

    var btnReq = document.getElementById("btnRequestResetOtp");
    var btnResend = document.getElementById("btnResendForgotOtp");
    if (isResend && btnResend) {
      btnResend.textContent = "...";
    } else if (btnReq) {
      btnReq.disabled = true;
      btnReq.innerHTML = "<i class='fa-solid fa-spinner fa-spin'></i> ĐANG GỬI MÃ...";
    }

    var otpCode = String(Math.floor(100000 + Math.random() * 900000));
    try {
      sessionStorage.setItem("mmo_forgot_otp", otpCode);
      sessionStorage.setItem("mmo_forgot_email", email);
      sessionStorage.setItem("mmo_forgot_time", String(Date.now()));
    } catch(e) {}

    var ACTIVE_GAS_OTP_URL = "https://script.google.com/macros/s/AKfycbylo1VU2SibsBmrxeCmWDCSm521HnW-Cd3vnmaKqJevPa4HPy4A_LyrQJ54T6BzgBI6Dg/exec";
    var gasRes = null;
    try {
      var otpUrl = ACTIVE_GAS_OTP_URL + "?action=sendPasswordResetOtp\x26email=" + encodeURIComponent(email) + "\x26otp=" + encodeURIComponent(otpCode);
      var rawRes = await fetch(otpUrl, { method: "GET" });
      gasRes = await rawRes.json();
      console.log("[ForgotPass] Direct OTP dispatch response:", gasRes);
    } catch(errDirect) {
      if (typeof callGasApi === "function") {
        try {
          gasRes = await callGasApi("sendPasswordResetOtp", { email: email, otp: otpCode });
        } catch(err) {}
      }
    }

    if (btnReq) {
      btnReq.disabled = false;
      btnReq.innerHTML = "<i class='fa-solid fa-paper-plane'></i> TIẾP TỤC / GỬI MÃ XÁC THỰC";
    }

    if (gasRes && gasRes.success === false) {
      if (typeof showToast === "function") showToast("⚠️ Máy chủ phản hồi: " + (gasRes.message || "Không thể gửi email. Vui lòng thử lại sau!"), "danger", 8000);
      return;
    }

    var s1 = document.getElementById("forgotStep1");
    var s2 = document.getElementById("forgotStep2");
    var otpInp = document.getElementById("forgotOtpInput");
    var targetEmailDisp = document.getElementById("forgotTargetEmailDisp");

    if (s1) s1.style.display = "none";
    if (s2) s2.style.display = "flex";
    if (targetEmailDisp) targetEmailDisp.textContent = email;

    if (otpInp) {
      otpInp.value = "";
      otpInp.focus();
    }

    if (typeof window.startForgotCooldown === "function") window.startForgotCooldown(60);

    if (typeof showToast === "function") {
      showToast("📧 Mã xác thực OTP đã được gửi đến email " + email + ". Vui lòng kiểm tra Hộp thư đến (hoặc hòm thư Spam/Rác) để lấy mã xác thực!", "success", 12000);
    }
  };

  window.handleConfirmPasswordReset = async function() {
    var email = (sessionStorage.getItem("mmo_forgot_email") || document.getElementById("forgotEmailInput")?.value || "").trim().toLowerCase();
    var savedOtp = sessionStorage.getItem("mmo_forgot_otp");
    var enteredOtp = (document.getElementById("forgotOtpInput")?.value || "").trim();
    var newPass = document.getElementById("forgotNewPassInput")?.value || "";
    var confirmPass = document.getElementById("forgotConfirmPassInput")?.value || "";

    if (!enteredOtp) {
      if (typeof showToast === "function") showToast("Vui lòng nhập mã xác thực OTP từ email của bạn!", "warning");
      var oInp = document.getElementById("forgotOtpInput");
      if (oInp) oInp.focus();
      return;
    }
    if (savedOtp && enteredOtp !== savedOtp) {
      if (typeof showToast === "function") showToast("⚠️ Mã xác thực OTP không chính xác. Vui lòng kiểm tra lại email!", "danger");
      return;
    }
    if (!newPass || newPass.length < 6) {
      if (typeof showToast === "function") showToast("Mật khẩu mới phải có ít nhất 6 ký tự!", "warning");
      return;
    }
    if (newPass !== confirmPass) {
      if (typeof showToast === "function") showToast("Mật khẩu xác nhận không khớp!", "warning");
      return;
    }

    var users = (typeof getRegisteredUsers === "function") ? getRegisteredUsers() : [];
    var updated = false;
    users.forEach(function(u) {
      if ((u.email || "").toLowerCase().trim() === email) {
        u.password = newPass;
        updated = true;
      }
    });
    if (!updated) {
      users.push({
        userId: "USR_" + Math.floor(100000 + Math.random() * 900000),
        name: email.split("@")[0],
        email: email,
        role: "MEMBER",
        balance: 0,
        password: newPass
      });
    }
    if (typeof saveRegisteredUsers === "function") saveRegisteredUsers(users);
    try { localStorage.setItem("mmo_registered_users", JSON.stringify(users)); } catch(e) {}

    var ACTIVE_GAS_OTP_URL = "https://script.google.com/macros/s/AKfycbylo1VU2SibsBmrxeCmWDCSm521HnW-Cd3vnmaKqJevPa4HPy4A_LyrQJ54T6BzgBI6Dg/exec";
    try {
      var resetUrl = ACTIVE_GAS_OTP_URL + "?action=resetPassword\x26email=" + encodeURIComponent(email) + "\x26newPassword=" + encodeURIComponent(newPass);
      await fetch(resetUrl, { method: "GET" });
    } catch(e) {
      if (typeof callGasApi === "function") {
        callGasApi("resetPassword", { email: email, newPassword: newPass }).catch(function() {});
      }
    }

    if (typeof showToast === "function") showToast("🎉 Đặt lại mật khẩu thành công! Vui lòng đăng nhập với mật khẩu mới.", "success");
    try {
      sessionStorage.removeItem("mmo_forgot_otp");
      sessionStorage.removeItem("mmo_forgot_email");
      sessionStorage.removeItem("mmo_forgot_time");
    } catch(e) {}

    if (typeof window.switchAuthTab === "function") window.switchAuthTab("login");
    var loginEmailInp = document.getElementById("loginEmailInput");
    var loginPassInp = document.getElementById("loginPassInput");
    if (loginEmailInp) loginEmailInp.value = email;
    if (loginPassInp) {
      loginPassInp.value = "";
      loginPassInp.focus();
    }
  };

  function bootMMOCdnApp() {
    if (window._mmoAppFullyInitialized) {
      if (typeof pollTimer !== "undefined" && pollTimer) clearInterval(pollTimer);
      return true;
    }
    if (typeof initMMOApplication === "function") {
      try {
        initMMOApplication();
        if (typeof renderBestSellers === "function") renderBestSellers();
        if (typeof renderRecommended === "function") renderRecommended();
        if (typeof renderProductGrid === "function") renderProductGrid();
      } catch(err) {
        console.error("bootMMOCdnApp init error:", err);
      }
      if (typeof pollTimer !== "undefined" && pollTimer) clearInterval(pollTimer);
      return true;
    }
    return false;
  }

  if (bootMMOCdnApp()) return;
  document.addEventListener("DOMContentLoaded", bootMMOCdnApp);
  window.addEventListener("load", bootMMOCdnApp);

  var sEl = document.getElementById("mmoCdnBundleJs");
  function triggerFastlyFallback() {
    if (window._cdnFallbackTriggered || window._mmoAppFullyInitialized) return;
    window._cdnFallbackTriggered = true;
    console.warn("CDN primary slow or failed, falling back to Fastly mirror...");
    var fb = document.createElement("script");
    fb.defer = true;
    fb.src = "https://fastly.jsdelivr.net/gh/digimarketmmo/muabantaikhoanmmo-cdn@v6.4.8/bundle.min.js?v=6.4.7";
    fb.onload = bootMMOCdnApp;
    document.body.appendChild(fb);
  }
  if (sEl) {
    sEl.addEventListener("load", bootMMOCdnApp);
    sEl.addEventListener("error", triggerFastlyFallback);
  }
  setTimeout(function() {
    if (!window._mmoAppFullyInitialized && typeof initMMOApplication !== "function") {
      triggerFastlyFallback();
    }
  }, 12000);

  var pollCount = 0;
  var pollTimer = setInterval(function() {
    pollCount++;
    if (bootMMOCdnApp() || pollCount > 100) {
      clearInterval(pollTimer);
    }
  }, 50);
})();
